entries[49285] = { ["name"] = "X-51 Nether-Rocket", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nA riding rocket! This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"First designed as a booster for a much larger rocket, the X-51 was determined to give the perfect thrust capacity for a single rider payload.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
entries[49286] = { ["name"] = "X-51 Nether-Rocket X-TREME", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nAn X-TREME riding rocket! This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"What it lacks in safety features it more than makes up for in speed and style. Not for the faint of heart.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
